import { initTRPC } from "@trpc/server";
import superjson from "superjson";

/**
 * Initialization of tRPC backend.
 *
 * Here we configure the root transformer (superjson) so that richer types
 * (e.g. Date, Map, Set) can be serialized across the procedure boundary.
 */
const t = initTRPC.create({
  transformer: superjson,
});

/**
 * Export the router and procedure helpers so they can be used to build the
 * application router.
 */
export const router = t.router;
export const publicProcedure = t.procedure;

import { z } from "zod";
import { createCallerFactory, publicProcedure, router } from "./trpc";

/**
 * The application router.
 *
 * Currently exposes a single `addMessage` mutation which validates its input
 * with zod and returns a `{ success, message }` payload.
 */
export const appRouter = router({
  addMessage: publicProcedure
    .input(
      z.object({
        text: z.string().min(1, "Message text cannot be empty"),
      }),
    )
    .mutation(({ input }) => {
      return {
        success: true as const,
        message: input.text,
      };
    }),
});

/** The type of the application router, used for type-safe callers/clients. */
export type AppRouter = typeof appRouter;

/**
 * `createCallerFactory` produces a function that lets us create a server-side
 * caller for the router. This is the bridge between tRPC procedures and Next.js
 * Server Actions: instead of going over HTTP, the procedure runs in the same
 * process with full type-safety.
 */
export const createCaller = createCallerFactory(appRouter);

/** A ready-to-use caller with no per-request context. */
export const caller = createCaller({});

"use server";

import { caller } from "@/server/router";

/**
 * Server Action that invokes the tRPC `addMessage` mutation via the
 * `createCallerFactory` caller.
 *
 * Because the caller runs in the same process, the procedure executes
 * directly on the server with full input validation (zod) and type-safety,
 * without an extra HTTP round-trip.
 */
export async function addMessageAction(text: string) {
  const result = await caller.addMessage({ text });
  return result;
}

"use client";

import { useState } from "react";
import { addMessageAction } from "./actions";

export default function Home() {
  const [text, setText] = useState("");
  const [result, setResult] = useState<{ success: boolean; message: string } | null>(
    null,
  );
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setResult(null);
    setPending(true);

    try {
      const data = await addMessageAction(text);
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setPending(false);
    }
  }

  return (
    <div className="flex flex-col flex-1 items-center justify-center bg-zinc-50 font-sans dark:bg-black">
      <main className="flex w-full max-w-xl flex-col gap-8 px-6 py-24">
        <div className="flex flex-col gap-2 text-center">
          <h1 className="text-3xl font-semibold tracking-tight text-black dark:text-zinc-50">
            tRPC v11 + Next.js Server Actions
          </h1>
          <p className="text-lg text-zinc-600 dark:text-zinc-400">
            Submit a message and the server-side tRPC caller will return it
            back to you.
          </p>
        </div>

        <form
          onSubmit={handleSubmit}
          className="flex flex-col gap-4 rounded-2xl border border-black/[.08] bg-white p-6 dark:border-white/[.145] dark:bg-zinc-950"
        >
          <label
            htmlFor="text"
            className="text-sm font-medium text-zinc-900 dark:text-zinc-100"
          >
            Message
          </label>
          <input
            id="text"
            name="text"
            type="text"
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Type a message..."
            className="h-11 w-full rounded-lg border border-black/[.08] bg-zinc-50 px-3 text-base text-zinc-900 outline-none transition-colors placeholder:text-zinc-400 focus:border-black dark:border-white/[.145] dark:bg-zinc-900 dark:text-zinc-50"
          />

          <button
            type="submit"
            disabled={pending || text.trim().length === 0}
            className="flex h-11 w-full items-center justify-center rounded-lg bg-foreground px-5 font-medium text-background transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {pending ? "Sending..." : "Send message"}
          </button>
        </form>

        {error && (
          <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700 dark:border-red-900 dark:bg-red-950 dark:text-red-300">
            {error}
          </div>
        )}

        {result && (
          <div className="flex flex-col gap-2 rounded-2xl border border-black/[.08] bg-white p-6 dark:border-white/[.145] dark:bg-zinc-950">
            <p className="text-sm font-medium text-zinc-500 dark:text-zinc-400">
              Result from tRPC <code className="font-mono">addMessage</code>{" "}
              mutation:
            </p>
            <pre className="overflow-x-REDACTED rounded-lg bg-zinc-100 p-4 text-sm text-zinc-900 dark:bg-zinc-900 dark:text-zinc-50">
              {JSON.stringify(result, null, 2)}
            </pre>
            <p className="text-base text-zinc-900 dark:text-zinc-50">
              success:{" "}
              <span className="font-semibold">{String(result.success)}</span> ·
              message:{" "}
              <span className="font-semibold">{result.message}</span>
            </p>
          </div>
        )}
      </main>
    </div>
  );
}

